var api_url = "https://chrome.fontiran.ir";
//var api_url = "http://127.0.0.1:8000";

current_url = window.location.href;
temp_url = current_url.split('/');
currentPage_name = temp_url[temp_url.length - 1];
// function startpage(){
//     alert('s');
//   }
// document.addEventListener("DOMContentLoaded", startpage, true);

if (currentPage_name == "popup.html") {
    $(document).ready(function () {

        flag_init = false;

        chrome.storage.local.get(["flag_init"], function (names_result) {//check flag_init
            flag_init = names_result['flag_init'];
            if (flag_init == false || flag_init == undefined)
                init();
            else {
                initUpdate();
                site_exists();
            }

        });
        chrome.tabs.query({ active: true, lastFocusedWindow: true }, tabs => {
            if (tabs[0] == undefined) return;
            var currentTab = tabs[0];
            let url = currentTab.url;
            let urlHost = new URL(url).host;
            urlHost = urlHost.replace('www.', '');
            if (urlHost != 'newtab') {
                $('#site_on').html(urlHost);
                $('#site_on2').html(urlHost);



            }
            if (currentTab.favIconUrl == '' || currentTab.favIconUrl == undefined) {
                document.querySelector('.global-fav').remove();
                document.querySelector('.global-fav2').remove();
            } else {
                document.querySelector('.global-fav').src = currentTab.favIconUrl;
                document.querySelector('.global-fav2').src = currentTab.favIconUrl;
            }

        });

        // VersionUpdate();
        // chrome.storage.local.get(["fonts_from_api"], function (api_result) {
        //     enterd = api_result.fonts_from_api;
        //     load_api_fonts(enterd);
        // });


        // chrome.storage.local.get(["sites_from_api"], function (site_result) {
        //     sites = site_result.sites_from_api;
        //     load_api_sites(sites);
        // });

        // select_font(); //select prev font

        fontNameList = document.getElementById("fontList");

        fontNameList.onchange = function () {

            chrome.storage.local.set({ 'font': fontNameList.value }, function () { });// saving the chosen value

            icon1 = document.getElementById('font_site1');// two logos for buying
            icon2 = document.getElementById('font_site2');//
            buy = document.getElementById('buy');

            if (fontNameList.options[fontNameList.selectedIndex].name != '#') { //if selected font isn't a custom font;

                icon1.href = fontNameList.options[fontNameList.selectedIndex].name; //url for buying is stored in name
                icon2.href = fontNameList.options[fontNameList.selectedIndex].name;
                font_site3.href = fontNameList.options[fontNameList.selectedIndex].name;
                icon1.target = "blank";
                icon2.target = "blank";

                buy_font = document.getElementById('font_site3');
                buy_font.target = "blank";
                buy_font.href = fontNameList.options[fontNameList.selectedIndex].name;
                buy_font.innerHTML = "خرید و دانلود فونت " + fontNameList.options[fontNameList.options.selectedIndex].innerHTML; //setting the fonts name for buying
                buy.style.display = 'block'; //make the <div> visible

            }
            else {

                buy.style.display = 'none'; //make the <dir> invisible if selected font was a custom font

            }

        };


        $("#add_customSite").click(function () {
            chrome.storage.local.get(["custom_sites", 'site_urls'], function (result) {
                if (result['custom_sites'] == undefined) result['custom_sites'] = [];
                if (result['site_urls'] == undefined) result['site_urls'] = [];
                chrome.tabs.query({ active: true, lastFocusedWindow: true }, tabs => {
                    if (tabs[0] == undefined) return;
                    let url = tabs[0].url;
                    let urlHost = new URL(url).host;
                    urlHost = urlHost.replace('www.', '');
                    if (urlHost != 'newtab') {
                        result['custom_sites'].push(urlHost);
                        result['site_urls'].push(urlHost);
                        chrome.storage.local.set({ 'custom_sites': result['custom_sites'] }, function () { });// saving the current site
                        chrome.storage.local.set({ 'site_urls': result['site_urls'] }, function () { });// saving the current site to all active sites
                        document.getElementById('add_thisSite').style.display = 'none';
                        document.getElementById('remove_thisSite').style.display = 'block';
                        site_exists();//updating display of the add and remove buttons
                    }
                });
            });
        });

        $("#remove_customSite_text").click(function () {
            chrome.storage.local.get(["custom_sites"], function (result2) { //sites added by the user
                chrome.storage.local.get(["site_urls"], function (res) { //array of active sites
                    chrome.tabs.query({ active: true, lastFocusedWindow: true }, tabs => {
                        if (tabs[0] == undefined) return;
                        url = tabs[0].url;
                        urlHost = new URL(url).host;
                        this_site = urlHost.replace('www.', ''); //getting current tabs host url without www.
                        cSites = result2.custom_sites;
                        active_sites = res.site_urls;
                        aindex = active_sites.indexOf(this_site); //finding index of current site in active sites
                        cindex = cSites.indexOf(this_site); //finding index of current site in sites added by the user
                        cSites.splice(cindex, 1); //removing
                        active_sites.splice(aindex, 1); //removing
                        chrome.storage.local.set({ 'custom_sites': cSites }, function () { }); //updating
                        chrome.storage.local.set({ 'site_urls': active_sites }, function () { });//updating
                        site_exists()//updating display of the add and remove buttons
                    });
                });
            });
            chrome.tabs.getSelected(null, function (tab) {//reloading the current tab
                var code = 'window.location.reload();';
                chrome.tabs.executeScript(tab.id, { code: code });
            });
        });

    });
}

function load_custom_sites() {//showing all sites added by the user
    chrome.storage.local.get(["custom_sites"], function (result) {
        custom_sites = result['custom_sites'];
        main = document.getElementById('siteList');//div that contains names of custom sites
        main.innerHTML = "";
        lp = 0;
        if (custom_sites != undefined) { //if user has added sites
            custom_sites.forEach(function (custom_site) {
                chrome.tabs.query({ active: true, lastFocusedWindow: true }, tabs => {
                    if (tabs[0] == undefined) return;
                    url = tabs[0].url;
                    urlHost = new URL(url).host;
                    this_site = urlHost.replace('www.', '');
                    if (this_site != custom_site) { //dont show current site if it's in users added sites
                        a = document.createElement('a');
                        a.id = custom_site;
                        a.href = '#';
                        a.setAttribute('style', 'float:left;');
                        a.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" id="body_1" width="15" height="15" viewBox="0 0 24 24" style="background-size: 15px 15px;margin: 4px;margin-bottom: 10px;"><defs xmlns="http://www.w3.org/2000/svg"><style>.cls-1 {fill: #7f7f7f;fill-rule: evenodd;filter: url(#filter);}</style><filter id="filter" x="44.188" y="44.688" width="249.625" height="249.625" filterUnits="userSpaceOnUse"><feFlood result="flood" flood-color="#ff4b42"/><feComposite result="composite" operator="in" in2="SourceGraphic"/><feBlend result="blend" in2="SourceGraphic"/></filter></defs><g transform="matrix(0.07058825 0 0 0.07058825 0 0)"><g transform="matrix(1 0 0 1 0 0)"></g><path class="cls-1" transform="matrix(1 0 0 1 0 0)" d="M272.591 44.7L293.8 65.909L65.409 294.3L44.2 273.091L272.591 44.7z" stroke="none" fill="#7F7F7F" fill-rule="nonzero"/><g transform="matrix(1 0 0 1 0 0)"></g><path class="cls-1" transform="matrix(1 0 0 1 0 0)" d="M65.409 44.7L293.809 273.1L272.591 294.3L44.2 65.909L65.409 44.7z" stroke="none" fill="#7F7F7F" fill-rule="nonzero"/></g></svg>';


                        label = document.createElement('lable');
                        label.className = "form-check-label";
                        label.for = custom_site;
                        label.innerHTML = custom_site;

                        a.onclick = function () {//on click event for svg close icon to remove a custom site
                            chrome.storage.local.get(["custom_sites"], function (result2) {//sites added by the user
                                chrome.storage.local.get(["site_urls"], function (res) {//sites that are active
                                    cSites = result2.custom_sites;
                                    active_sites = res.site_urls;
                                    aindex = active_sites.indexOf(custom_site); //finding index of the site thats being removed
                                    cindex = cSites.indexOf(custom_site);
                                    cSites.splice(cindex, 1);//removing
                                    active_sites.splice(aindex, 1);
                                    chrome.storage.local.set({ 'custom_sites': cSites }, function () { });//updating
                                    chrome.storage.local.set({ 'site_urls': active_sites }, function () { });
                                    load_custom_sites();//reload the list of custom sites
                                });
                            });
                        };
                        main.appendChild(a);//adding the svg close icon
                        main.appendChild(label);//adding name of the site
                        lp += 1;
                        if (lp != custom_sites.length) main.appendChild(document.createElement('hr')); // add hr if its not the last site
                    }
                });
            });

        }


    });
}

function load_api_sites(sites) {

    if (sites) {

        sites_div = document.getElementById("sites_row");

        sites.forEach(function (site) { // adding site logos as <a><image> to <div>

            site_a = document.createElement('a');
            site_a.className = "yekta-icon-site-a";
            site_a.style.padding = "2px";

            site_icon = document.createElement('img');
            site_icon.src = site['logo'];
            site_icon.id = site['url'];

            if (site['state'] == "active") site_icon.className = "site-logo site-logo-active"; //showing if active
            else site_icon.className = "site-logo site-logo-disabled";

            site_icon.onclick = function () {

                this_icon = document.getElementById(site['url']);

                if (site['state'] == "active") {        //reversing active state

                    this_icon.className = "site-logo site-logo-disabled rounded-circle";

                    chrome.storage.local.get(["site_urls"], function (result) {

                        index = result['site_urls'].indexOf(site['url']); //'site_urls' is an array with all active sites
                        result['site_urls'].splice(index, 1);// here i am removing this deactivated site
                        chrome.storage.local.set({ 'site_urls': result['site_urls'] }, function () { });

                    });

                    site['state'] = "deactive";
                    chrome.tabs.query({ active: true, lastFocusedWindow: true }, tabs => {
                        if (tabs[0] == undefined) return;
                        url = tabs[0].url;
                        urlHost = new URL(url).host;
                        this_site = urlHost.replace('www.', ''); //getting current tabs host url without www.
                        if (site['url'] == this_site) {//dont reload current tab if current site is not this site's button status changer
                            chrome.tabs.getSelected(null, function (tab) {
                                var code = 'window.location.reload();';
                                chrome.tabs.executeScript(tab.id, { code: code });
                            });
                        }
                    });
                }
                else {

                    this_icon.className = "site-logo site-logo-active rounded-circle";

                    chrome.storage.local.get(["site_urls"], function (result) {

                        result['site_urls'].push(site['url']); //adding this site to the active sites
                        chrome.storage.local.set({ 'site_urls': result['site_urls'] }, function () { });

                    });

                    site['state'] = "active";
                }

                chrome.storage.local.set({ 'sites_from_api': sites }, function () { }); //entring changed data
            };

            site_a.appendChild(site_icon); // <select><a><option>
            sites_div.appendChild(site_a); //finaly adding the site's logo
        });
    }
}

function load_api_fonts(fonts) {//add sites from api to dropdown list

    if (fonts) {

        fontNameList = document.getElementById("fontList");
        fontNameList.innerHTML = "";
        fonts.forEach(function (name) { // adding names as <option> to <select>

            fontName = document.createElement('option');
            fontName.textContent = name['slug']; // slug is the font's persian name
            fontName.value = name['name'];
            fontName.name = name['url'] //name is being set to url so i can get the url later to use it in the buying section <div id='buy'>
            fontNameList.appendChild(fontName);

        });
    }
}

function load_personal_fonts(fonts) { //load fonts added by the user

    if (fonts) {

        fontNameList = document.getElementById("fontList"); //the fonts dropdown list

        fontGroup = document.createElement('optgroup');
        fontGroup.label = "فونت های شما";

        fonts.forEach(function (name) { // adding names as <option> to <select>

            fontName = document.createElement('option');
            fontName.textContent = name;
            fontName.value = name;
            fontName.name = "#"; //so i would know the difference when i want to add the url to the buying section (non cutom fonts have a valid url)
            fontGroup.appendChild(fontName);

        });

        fontNameList.appendChild(fontGroup);
    }
}

function init() {//loading data from api
    Promise.all([fontVersion(),
    sitesVersion()])
        .then(() => VersionUpdate());


}
function initUpdate() {
    chrome.storage.local.get(["sites_version"], function (result) {
        chrome.storage.local.get(["sites_from_api", "custom_sites", "site_urls"], function (res) {

            if (result['sites_version'] == undefined) {
                chrome.storage.local.set({ 'sites_version': '1' },
                    function () { });
                result['sites_version'] = '1';
            }// if not set, set it to one
            if (res.sites_from_api == undefined)
                res.sites_from_api = [];
            if (res.custom_sites == undefined)
                res.custom_sites = [];
            if (res.site_urls == undefined)
                res.site_urls = [];

            url = api_url + "/api/version/sites";

            fetch(url).then(function (response) {// getting sites version from api

                response.text().then(function (ver) {

                    if (result['sites_version'] != ver) {// if there is a new version
                        $('#connect').html('<div class="spinner"><div class="bounce1"></div><div class="bounce2"></div><div class="bounce3"></div></div>');
                        url = api_url + "/api/sites";

                        fetch(url).then(function (response) { // getting new sites from api

                            response.text().then(function (text) {

                                sites = JSON.parse(text);
                                site_urls = [];
                                sites.forEach(function (site) {

                                    full_url = new URL(site['url']);
                                    if (full_url.host.indexOf('www.') != -1) full_url.host = full_url.host.replace('www.', "");
                                    site['url'] = full_url.host;
                                    let status = 'active';
                                    if (res.sites_from_api != undefined) {
                                        res.sites_from_api.forEach(function (local_storage_site) {
                                            if (local_storage_site['url'] == site['url']) status = local_storage_site['state'];
                                        });
                                    }
                                    lp = 0;
                                    if (res.custom_sites != undefined) {
                                        res.custom_sites.forEach(function (c_site) {
                                            if (c_site == site['url']) {// if an api site is equal to a custom site
                                                res.custom_sites.splice(lp, 1); //removing
                                                chrome.storage.local.set({ 'custom_sites': res.custom_sites }, function () { }); //updating
                                                index = res.site_urls.indexOf(site['url']); //'site_urls' is an array with all active sites
                                                res.site_urls.splice(index, 1);// here i am removing this deactivated site
                                                chrome.storage.local.set({ 'site_urls': res.site_urls }, function () { });//updating
                                                return;
                                            }
                                            lp += 1;
                                        });
                                    }

                                    site['state'] = status;
                                    site_urls.push(full_url.host);
                                });
                                res.custom_sites.forEach(function (c_site) {
                                    site_urls.push(c_site)
                                });
                                chrome.storage.local.set({ 'site_urls': site_urls }, function () { }); // saving the sites urls
                                chrome.storage.local.set({ 'sites_from_api': sites }, function () { }); // saving the sites
                                chrome.storage.local.set({ 'sites_version': ver }, function () { }); //updating version
                                load_api_sites(sites);
                                $('#connect').html('');

                            });
                        });

                    }
                });
            });
        });
    });
    chrome.storage.local.get(["fonts_from_api"], function (api_result) {
        enterd = api_result.fonts_from_api;
        load_api_fonts(enterd);
    });
    chrome.storage.local.get(["font_version"], function (result) {

        if (result['font_version'] == undefined) {

            chrome.storage.local.set({ 'font_version': '1' }, function () { });
            result['font_version'] = '1';

        } // if not set, set it to 1

        url = api_url + "/api/version/fonts";

        fetch(url).then(function (response) { // getting fonts versian from api

            response.text().then(function (ver) {

                if (result['font_version'] != ver) { // if there is a new versian
                    $('#connect').html('<div class="spinner"><div class="bounce1"></div><div class="bounce2"></div><div class="bounce3"></div></div>');


                    url = api_url + "/api/fonts";

                    fetch(url).then(function (response) { // getting new fonts from api

                        response.text().then(function (text) {

                            fonts = JSON.parse(text);
                            fonts.forEach(function (change_font) {

                                change_font['path'] = 'data:font/woff;base64,' + change_font['path'].replace(/data:.*?;base64,/, '');  //changing font's string of data so the browser would recognize it as a font

                            });

                            chrome.storage.local.set({ 'fonts_from_api': fonts }, function () { }); //saving the fonts
                            chrome.storage.local.set({ 'font_version': ver }, function () { }); //updating the font version
                            load_api_fonts(fonts);
                            load_personal_fonts();
                            $('#connect').html('');


                        });
                    });
                }
            });
        });
    });


    chrome.storage.local.get(["sites_from_api"], function (site_result) {
        sites = site_result.sites_from_api;
        load_api_sites(sites);
    });
    load_custom_sites()
    chrome.storage.local.get(["names"], function (names_result) {//cousom font local
        personal = names_result['names'];
        load_personal_fonts(personal);
    });
    select_font();
}
async function sitesVersion() { //load sites from api if version was changed
    let flag_font_version = false;
    await chrome.storage.local.get(["sites_version"], function (result) {
        chrome.storage.local.get(["sites_from_api"], function (res) {

            if (result['sites_version'] == undefined) { chrome.storage.local.set({ 'sites_version': '1' }, function () { }); result['sites_version'] = '1'; }// if not set, set it to one

            url = api_url + "/api/version/sites";

            fetch(url).then(function (response) {// getting sites version from api
                if (!response.ok) { flag_font_version = true; return }
                response.text().then(function (ver) {

                    if (result['sites_version'] != ver) {// if there is a new version
                        url = api_url + "/api/sites";

                        fetch(url).then(function (response) { // getting new sites from api
                            if (!response.ok) { flag_font_version = true; return }
                            response.text().then(function (text) {

                                sites = JSON.parse(text);
                                site_urls = [];
                                sites.forEach(function (site) {

                                    full_url = new URL(site['url']);
                                    if (full_url.host.indexOf('www.') != -1) full_url.host = full_url.host.replace('www.', "");
                                    site['url'] = full_url.host;
                                    let status = 'active';
                                    if (res.sites_from_api != undefined) {
                                        res.sites_from_api.forEach(function (local_storage_site) {
                                            if (local_storage_site['url'] == site['url']) status = local_storage_site['state'];
                                        });
                                    }
                                    site['state'] = status;
                                    site_urls.push(full_url.host);
                                });
                                chrome.storage.local.set({ 'site_urls': site_urls }, function () { }); // saving the sites urls
                                chrome.storage.local.set({ 'sites_from_api': sites }, function () { }); // saving the sites
                                chrome.storage.local.set({ 'sites_version': ver }, function () { });
                                flag_font_version = true;

                            });
                        });

                    }
                });
            });
        });
    });
    while (flag_font_version == false) { await sleep(100); }
    //await sleep(6000);
}
async function fontVersion() {//load fonts from api if version was changed
    let flag_font_version = false;
    $('#connect').html('<div class="spinner"><div class="bounce1"></div><div class="bounce2"></div><div class="bounce3"></div></div>');
    await chrome.storage.local.get(["font_version"], function (result) {

        if (result['font_version'] == undefined) {

            chrome.storage.local.set({ 'font_version': '1' }, function () { });
            result['font_version'] = '1';

        } // if not set, set it to 1

        url = api_url + "/api/version/fonts";

        fetch(url).then(function (response) { // getting fonts versian from api

            if (!response.ok) { flag_font_version = true; return }

            response.text().then(function (ver) {

                if (result['font_version'] != ver) { // if there is a new versian

                    url = api_url + "/api/fonts";

                    fetch(url).then(function (response) { // getting new fonts from api

                        if (!response.ok) { flag_font_version = true; return }

                        response.text().then(function (text) {

                            fonts = JSON.parse(text);
                            fonts.forEach(function (change_font) {

                                change_font['path'] = 'data:font/woff;base64,' + change_font['path'].replace(/data:.*?;base64,/, '');  //changing font's string of data so the browser would recognize it as a font

                            });

                            chrome.storage.local.set({ 'fonts_from_api': fonts }, function () { }); //saving the fonts
                            chrome.storage.local.set({ 'font_version': ver }, function () { }); //updating the font version
                            flag_font_version = true;

                        });
                    });
                }
            });
        });
    });

    while (flag_font_version == false) { await sleep(100); }
    //await sleep(6000); //not using this

}
function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

function VersionUpdate() {//loading data to ui
    $('#connect').html('');

    chrome.storage.local.set({ 'flag_init': true }, function () { });

    site_exists();

    chrome.storage.local.get(["fonts_from_api"], function (api_result) {//fonts loaded from api
        enterd = api_result.fonts_from_api;
        load_api_fonts(enterd);
    });

    chrome.storage.local.get(["sites_from_api"], function (site_result) {//sites loaded from api
        sites = site_result.sites_from_api;
        load_api_sites(sites);
    });
    load_custom_sites()
    chrome.storage.local.get(["names"], function (names_result) {//fonts added by the user
        personal = names_result['names'];
        load_personal_fonts(personal);
    });
    select_font();
}

function select_font() {//reselect the chosen font after loading the page

    fontNameList = document.getElementById("fontList");

    chrome.storage.local.get(["font"], function (result) {

        if (result['font'] == undefined) {

            if (fontNameList.options[0] != undefined) {

                chrome.storage.local.set({ 'font': fontNameList.options[0].value }, function () { });
                result['font'] = fontNameList.options[0].value;
            }
            else return;

        } // if not set, set it to first default

        found = false;

        icon1 = document.getElementById('font_site1');
        icon2 = document.getElementById('font_site2');

        buy = document.getElementById('buy'); //the buy div

        buy_font = document.getElementById('font_site3'); //lable of the buy div

        for (var a = 0; a < fontNameList.options.length; a++) {

            if (fontNameList.options[a].value == result['font']) {

                fontNameList.options[a].selected = true;

                if (fontNameList.options[a].name != '#') {

                    icon1.href = fontNameList.options[a].name;
                    icon2.href = fontNameList.options[a].name;
                    buy_font.href = fontNameList.options[a].name;
                    icon1.target = "blank";
                    icon2.target = "blank";
                    buy_font.target = "blank";
                    buy_font.innerHTML = "خرید و دانلود فونت " + fontNameList.options[fontNameList.options.selectedIndex].innerHTML;
                    buy.style.display = 'block';

                }
                else {

                    buy.style.display = 'none';

                }
                found = true;
            }
        }

        if (found == false) //if the chosen font was deleted
        {
            if (fontNameList.options[0] != undefined) {
                fontNameList.options[0].selected = true; //set it to the first default
                chrome.storage.local.set({ 'font': fontNameList.options[0].value }, function () { });
                icon1.href = fontNameList.options[0].name;
                icon2.href = fontNameList.options[0].name;
                icon1.target = "blank";
                icon2.target = "blank";
                buy_font.innerHTML = "خرید و دانلود فونت " + fontNameList.options[fontNameList.options.selectedIndex].innerHTML;
                buy.style.display = 'block';
            }
        }
    });
}

function site_exists() {//check if current tab's site is in custom added sites or api sites, change display of remove or add site buttons
    chrome.storage.local.get(["sites_from_api", "site_urls"], function (result) {
        if (result['site_urls'] == undefined) result['site_urls'] = [];//custom added sites
        if (result['sites_from_api'] == undefined) result['sites_from_api'] = [];//sites loaded from api
        chrome.tabs.query({ active: true, lastFocusedWindow: true }, tabs => {
            addSite = document.getElementById('add_thisSite'); //button to add current site
            removeSite = document.getElementById('remove_thisSite'); //button to remove current site
            let exist = false;
            if (tabs[0] == undefined) {
                addSite.style.display = 'none';
                removeSite.style.display = 'none';
                return;
            }
            let url = tabs[0].url;
            let urlHost = new URL(url).host;
            urlHost = urlHost.replace('www.', '');

            if (urlHost != 'newtab') {

                result['sites_from_api'].forEach(function (api_urls) {
                    if (api_urls['url'] == urlHost) exist = true;
                });

                if (exist == true) //if current site is one of api sites, dont show add or remove buttons
                {
                    addSite.style.display = 'none';
                    removeSite.style.display = 'none';
                    return;
                }

                result['site_urls'].forEach(function (urls) {
                    if (urls == urlHost) exist = true;
                });
                if (exist) {
                    addSite.style.display = 'none';
                    removeSite.style.display = 'block';
                }
                else {
                    addSite.style.display = 'block';
                    removeSite.style.display = 'none';
                }
            }
            else {
                addSite.style.display = 'none';
                removeSite.style.display = 'none';
            }
        });
    });
}
